// Shared site script: renders the header/footer and every <div class="chart" data-dataset="...">.
// A chart card reads docs/data/<dataset>.json (generated by `python -m pipeline.build_site`).
// Optional data-chart="line|stacked-area|stacked-bar|hbar" overrides the type from datasets.yml.

const PAGES = [
  ["index.html", "Overview"],
  ["national.html", "National"],
  ["buildings.html", "Buildings"],
  ["electricity.html", "Electricity"],
  ["renewables.html", "Renewables"],
  ["heat.html", "Heat"],
  ["mobility.html", "Mobility"],
  ["sources.html", "Sources"],
  ["library.html", "Library"],
];

const REPO = "https://github.com/BartonChenTW/Swiss-energy-system-data";

const REFERENCE_TYPES = { report: "Reports", standard: "Standards & norms", dashboard: "Dashboards", website: "Websites", tool: "Tools", model: "Models", portal: "Data portals" };

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const fmt = (v) => (v == null ? "–" : v.toLocaleString("en-CH", { maximumFractionDigits: 2 }));
const fmtDate = (iso) => (iso ? new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }) : "");

// Light/dark: an explicit choice is stored by the header button (applied early by theme.js);
// otherwise the page follows the operating system.
const systemDark = matchMedia("(prefers-color-scheme: dark)");
const currentTheme = () => document.documentElement.dataset.theme || (systemDark.matches ? "dark" : "light");
const ICONS = {
  // shown in light mode: switch to dark
  moon: '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path fill="currentColor" d="M21 14.5A8.5 8.5 0 0 1 9.5 3a8.5 8.5 0 1 0 11.5 11.5Z"/></svg>',
  // shown in dark mode: switch to light
  sun: '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><circle cx="12" cy="12" r="4.5" fill="currentColor"/><g stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 2v2M12 20v2M2 12h2M20 12h2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></g></svg>',
};

function updateThemeToggle(button) {
  const dark = currentTheme() === "dark";
  button.innerHTML = dark ? ICONS.sun : ICONS.moon;
  button.setAttribute("aria-label", dark ? "Switch to light mode" : "Switch to dark mode");
  button.title = button.getAttribute("aria-label");
}

function renderChrome() {
  const here = location.pathname.split("/").pop() || "index.html";
  const header = document.getElementById("site-header");
  if (header) {
    header.innerHTML = `<div class="wrap header-inner">
      <a class="brand" href="index.html">Swiss Energy System Data</a>
      <nav>${PAGES.map(([href, label]) => `<a href="${href}"${href === here ? ' aria-current="page"' : ""}>${label}</a>`).join("")}</nav>
      <button class="theme-toggle" type="button" data-theme-toggle></button>
    </div>`;
    const toggle = header.querySelector("[data-theme-toggle]");
    updateThemeToggle(toggle);
    toggle.addEventListener("click", () => {
      const next = currentTheme() === "dark" ? "light" : "dark";
      document.documentElement.dataset.theme = next;
      try { localStorage.setItem("theme", next); } catch {}
      updateThemeToggle(toggle);
      recolorCharts();
    });
  }
  const footer = document.getElementById("site-footer");
  if (footer) {
    footer.innerHTML = `<div class="wrap">Data from Swiss federal offices and other publishers, used under their terms —
      see <a href="sources.html">Sources</a>. Built from the <a href="${REPO}">open pipeline on GitHub</a>.
      <div class="version" data-version></div></div>`;
    renderVersion(footer.querySelector("[data-version]"));
  }
}

// "Version 0.5.0 · built 29 Sep 2026 from a16cbca · Changelog", from docs/data/version.json.
async function renderVersion(el) {
  try {
    const v = await loadJSON("data/version.json");
    const sha = v.commit ? ` from <a href="${REPO}/commit/${esc(v.commit)}"><code>${esc(v.commit.slice(0, 7))}</code></a>` : "";
    el.innerHTML = `Version ${esc(v.version)}${v.unreleased ? " + unreleased changes" : ""} · built ${esc(fmtDate(v.built))}${sha}
      · <a href="changelog.html">Changelog</a>`;
  } catch {
    el.innerHTML = `<a href="changelog.html">Changelog</a>`;
  }
}

// Changelog bullets are Markdown: support `code` and [text](url), escape the rest.
const inlineMd = (s) => esc(s)
  .replace(/`([^`]+)`/g, "<code>$1</code>")
  .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2">$1</a>');

async function renderChangelog(el) {
  try {
    const { changelog } = await loadJSON("data/version.json");
    el.innerHTML = changelog.map((v) => `
      <section class="card release">
        <h2>${v.version === "Unreleased" ? "Unreleased" : `Version ${esc(v.version)}`}${v.date ? ` <span class="muted">${esc(fmtDate(v.date))}</span>` : ""}</h2>
        ${v.sections.filter((s) => s.items.length).map((s) => `<h3>${esc(s.title)}</h3>
          <ul>${s.items.map((i) => `<li>${inlineMd(i)}</li>`).join("")}</ul>`).join("")}
      </section>`).join("");
  } catch (err) {
    el.innerHTML = `<p class="error">Could not load the changelog (${esc(err.message)}). Run <code>python -m pipeline.build_site</code> first.</p>`;
  }
}

const cache = new Map();
function loadJSON(path) {
  if (!cache.has(path)) {
    cache.set(path, fetch(path).then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    }));
  }
  return cache.get(path);
}

// ---------- chart configs ----------

function chartConfig(ds, type) {
  const palette = ds.palette === "sequential"
    ? Array.from({ length: ds.series.length }, (_, i) => css(`--seq-${Math.min(7, i + 1)}`))
    : Array.from({ length: 8 }, (_, i) => css(`--series-${i + 1}`));
  const surface = css("--surface");
  const muted = css("--text-muted");
  const grid = css("--grid");
  const axis = css("--axis");
  const unit = ds.unit;

  const scales = {
    x: { grid: { display: false }, border: { color: axis }, ticks: { color: muted } },
    y: { beginAtZero: true, grid: { color: grid }, border: { display: false }, ticks: { color: muted },
         title: { display: true, text: unit, color: muted } },
  };
  const tooltip = { callbacks: { label: (c) => ` ${c.dataset.label || c.label}: ${fmt(c.parsed[type === "hbar" ? "x" : "y"])} ${unit}` } };
  const legend = {
    display: ds.series.length > 1 && type !== "hbar",
    position: "top", align: "start",
    labels: { color: css("--text-secondary"), boxWidth: 12, boxHeight: 12, useBorderRadius: true, borderRadius: 2 },
  };

  if (type === "hbar") {
    // Latest year, one bar per category.
    const last = ds.years.length - 1;
    return {
      type: "bar",
      data: {
        labels: ds.series.map((s) => s.name),
        datasets: [{ label: String(ds.years[last]), data: ds.series.map((s) => s.values[last]),
                     backgroundColor: palette[0], borderRadius: 4, borderSkipped: "start", maxBarThickness: 28 }],
      },
      options: {
        indexAxis: "y", maintainAspectRatio: false,
        scales: {
          x: { ...scales.y, title: { display: true, text: `${unit} (${ds.years[last]})`, color: muted } },
          y: { grid: { display: false }, border: { color: axis }, ticks: { color: css("--text-secondary") } },
        },
        plugins: { legend: { display: false }, tooltip },
      },
    };
  }

  const stacked = type === "stacked-area" || type === "stacked-bar";
  const datasets = ds.series.map((s, i) => {
    const color = palette[i % palette.length];
    if (type === "stacked-bar") {
      return { label: s.name, data: s.values, backgroundColor: color, borderColor: surface, borderWidth: { top: 2 }, borderSkipped: "bottom" };
    }
    return {
      label: s.name, data: s.values, borderColor: color, borderWidth: 2,
      backgroundColor: type === "stacked-area" ? color + "cc" : color,
      fill: type === "stacked-area" ? (i === 0 ? "origin" : "-1") : false,
      pointRadius: 0, pointHoverRadius: 5, pointHoverBorderColor: surface, pointHoverBorderWidth: 2, tension: 0,
    };
  });

  return {
    type: type === "stacked-bar" ? "bar" : "line",
    data: { labels: ds.years, datasets },
    options: {
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      scales: { x: { ...scales.x, stacked }, y: { ...scales.y, stacked } },
      plugins: { legend, tooltip: { ...tooltip, itemSort: stacked ? (a, b) => b.datasetIndex - a.datasetIndex : undefined } },
    },
  };
}

function dataTable(ds) {
  const head = `<tr><th>Category</th>${ds.years.map((y) => `<th>${y}</th>`).join("")}</tr>`;
  const rows = ds.series.map((s) => `<tr><td>${esc(s.name)}</td>${s.values.map((v) => `<td>${fmt(v)}</td>`).join("")}</tr>`).join("");
  return `<div class="table-scroll"><table><thead>${head}</thead><tbody>${rows}</tbody></table></div>`;
}

// ---------- rendering ----------

function coverageTag(ds) {
  if (ds.coverage === "regional") {
    return `<span class="tag tag-regional" title="Covers only ${esc(ds.region)}, not all of Switzerland">Regional · ${esc(ds.region)}</span>`;
  }
  return ds.coverage === "national" ? '<span class="tag tag-national" title="Covers all of Switzerland">National · Switzerland</span>' : "";
}

const charts = [];

// Stacked charts with several series can also be shown as one line per series,
// which makes each series' trend easier to read.
const switchable = (type, ds) => (type === "stacked-area" || type === "stacked-bar") && ds.series.length > 1;

async function renderCard(el) {
  const id = el.dataset.dataset;
  el.classList.add("card");
  try {
    const ds = await loadJSON(`data/${id}.json`);
    const type = el.dataset.chart || ds.chart || "line";
    el.innerHTML = `
      <div class="card-head"><h3>${esc(ds.title)}</h3><span class="tags-head">${coverageTag(ds)}${ds.status === "sample" ? '<span class="badge" title="Placeholder values — not official statistics">Sample data</span>' : ""}</span></div>
      <p class="card-sub">${esc(ds.description)} <span>(${esc(ds.unit)})</span></p>
      ${switchable(type, ds) ? `<div class="view-switch" role="group" aria-label="Chart view">
        <button type="button" data-view="${type}" aria-pressed="true">Stacked</button><button type="button" data-view="line" aria-pressed="false">Lines</button>
      </div>` : ""}
      <div class="canvas-box"><canvas role="img" aria-label="${esc(ds.title)}, ${esc(ds.unit)}"></canvas></div>
      <details><summary>Data table</summary>${dataTable(ds)}</details>
      <p class="card-foot">Source: <a href="${esc(ds.source.url)}">${esc(ds.source.name)}</a>, ${esc(ds.source.publisher)}.
        ${ds.provenance?.retrieved ? `Retrieved ${fmtDate(ds.provenance.retrieved)}.` : ""}
        ${ds.provenance?.notes ? `<br>${esc(ds.provenance.notes)}` : ""}</p>`;
    const canvas = el.querySelector("canvas");
    if (type === "hbar") el.querySelector(".canvas-box").style.height = `${Math.max(300, ds.series.length * 30 + 70)}px`;
    const entry = { canvas, ds, type, chart: new Chart(canvas, chartConfig(ds, type)) };
    charts.push(entry);
    el.querySelectorAll("[data-view]").forEach((button) => button.addEventListener("click", () => {
      if (entry.type === button.dataset.view) return;
      entry.type = button.dataset.view;
      el.querySelectorAll("[data-view]").forEach((b) => b.setAttribute("aria-pressed", String(b === button)));
      entry.chart.destroy();
      entry.chart = new Chart(canvas, chartConfig(ds, entry.type));
    }));
  } catch (err) {
    el.innerHTML = `<p class="error">Could not load <code>${esc(id)}</code> (${esc(err.message)}). Run <code>python -m pipeline.build_site</code> first.</p>`;
  }
}

async function renderSources(el) {
  try {
    const { sources, datasets } = await loadJSON("data/catalog.json");
    const rows = sources.map((s) => {
      const used = datasets.filter((d) => d.source === s.id).map((d) => esc(d.title)).join("<br>") || "<em>planned</em>";
      return `<tr><td><a href="${esc(s.url)}">${esc(s.name)}</a><div class="muted">${esc(s.publisher)}</div></td>
        <td>${esc(s.theme)}</td><td>${esc(s.frequency)}</td><td>${esc(s.terms)}</td><td>${used}</td></tr>`;
    }).join("");
    el.innerHTML = `<div class="table-scroll"><table class="sources">
      <thead><tr><th>Source</th><th>Theme</th><th>Frequency</th><th>Terms of use</th><th>Datasets on this site</th></tr></thead>
      <tbody>${rows}</tbody></table></div>`;
  } catch (err) {
    el.innerHTML = `<p class="error">Could not load the catalog (${esc(err.message)}).</p>`;
  }
}

async function renderLibrary(el) {
  try {
    const { references } = await loadJSON("data/catalog.json");
    const themes = [...new Set(references.flatMap((r) => r.themes))].sort();
    el.innerHTML = `
      <div class="filters">
        <label>Theme <select data-filter="theme"><option value="">All</option>${themes.map((t) => `<option>${esc(t)}</option>`).join("")}</select></label>
        <label>Type <select data-filter="type"><option value="">All</option>${Object.entries(REFERENCE_TYPES).map(([k, v]) => `<option value="${k}">${v}</option>`).join("")}</select></label>
      </div>
      <div data-list></div>`;
    const list = el.querySelector("[data-list]");
    const draw = () => {
      const theme = el.querySelector('[data-filter="theme"]').value;
      const type = el.querySelector('[data-filter="type"]').value;
      const shown = references.filter((r) => (!theme || r.themes.includes(theme)) && (!type || r.type === type));
      list.innerHTML = Object.entries(REFERENCE_TYPES).map(([key, label]) => {
        const group = shown.filter((r) => r.type === key);
        if (!group.length) return "";
        return `<h2>${label}</h2><div class="refs">${group.map((r) => `
          <article class="card ref">
            <h3><a href="${esc(r.url)}">${esc(r.title)}</a></h3>
            <p class="muted">${esc(r.publisher)}${r.year ? `, ${r.year}` : ""}${r.language ? ` · ${esc(r.language)}` : ""}</p>
            ${r.description ? `<p>${esc(r.description)}</p>` : ""}
            <p class="tags">${r.themes.map((t) => `<span>${esc(t)}</span>`).join("")}<span class="muted">checked ${esc(r.checked)}</span></p>
          </article>`).join("")}</div>`;
      }).join("") || `<p class="muted">Nothing matches these filters.</p>`;
    };
    el.querySelectorAll("select").forEach((s) => s.addEventListener("change", draw));
    draw();
  } catch (err) {
    el.innerHTML = `<p class="error">Could not load the catalog (${esc(err.message)}).</p>`;
  }
}

// ---------- EV profile data study (Mobility page), from references with an `ev_profile` block ----------

const EV_REGIONS = { Switzerland: "Switzerland", Europe: "Europe (outside Switzerland)", World: "Rest of the world" };
const EV_DATA = { sessions: "Sessions", load: "Load profile", driving: "Driving", status: "Status", synthetic: "Synthetic" };
const EV_ACCESS = { open: "Open download", registration: "Free registration", restricted: "Restricted" };

async function renderEvProfiles(el) {
  try {
    const { references } = await loadJSON("data/catalog.json");
    const entries = references.filter((r) => r.ev_profile);
    const accessRank = { open: 0, registration: 1, restricted: 2 };
    el.innerHTML = `
      <div class="filters">
        <label>Data <select data-filter="data"><option value="">All</option>${Object.entries(EV_DATA).map(([k, v]) => `<option value="${k}">${v}</option>`).join("")}</select></label>
        <label>Access <select data-filter="access"><option value="">All</option>${Object.entries(EV_ACCESS).map(([k, v]) => `<option value="${k}">${v}</option>`).join("")}</select></label>
      </div>
      <div data-list></div>`;
    const list = el.querySelector("[data-list]");
    const draw = () => {
      const data = el.querySelector('[data-filter="data"]').value;
      const access = el.querySelector('[data-filter="access"]').value;
      const shown = entries.filter((r) => (!data || r.ev_profile.data.includes(data)) && (!access || r.ev_profile.access === access));
      list.innerHTML = Object.entries(EV_REGIONS).map(([key, label]) => {
        const group = shown.filter((r) => r.ev_profile.region === key)
          .sort((a, b) => accessRank[a.ev_profile.access] - accessRank[b.ev_profile.access]);
        if (!group.length) return "";
        const rows = group.map((r) => {
          const ev = r.ev_profile;
          return `<tr>
            <td><a href="${esc(r.url)}">${esc(r.title)}</a><div class="muted">${esc(r.publisher)}${r.year ? `, ${r.year}` : ""}</div></td>
            <td><span class="tags">${ev.data.map((t) => `<span>${esc(EV_DATA[t])}</span>`).join("")}</span></td>
            <td>${esc(ev.coverage)}</td>
            <td>${esc(ev.resolution)}</td>
            <td><span class="access access-${esc(ev.access)}">${esc(EV_ACCESS[ev.access])}</span><div class="muted">${esc(ev.licence)}</div></td>
          </tr>`;
        }).join("");
        return `<h3 class="ev-region">${label} <span class="muted">${group.length}</span></h3>
          <div class="table-scroll"><table class="sources ev-profiles">
            <thead><tr><th>Dataset</th><th>Data</th><th>Coverage</th><th>Resolution</th><th>Access and licence</th></tr></thead>
            <tbody>${rows}</tbody></table></div>`;
      }).join("") || `<p class="muted">Nothing matches these filters.</p>`;
    };
    el.querySelectorAll("select").forEach((s) => s.addEventListener("change", draw));
    draw();
  } catch (err) {
    el.innerHTML = `<p class="error">Could not load the catalog (${esc(err.message)}).</p>`;
  }
}

function applyChartDefaults() {
  Chart.defaults.font.family = css("--font");
  Chart.defaults.color = css("--text-muted");
}

// Charts read colours from CSS variables when drawn, so redraw them after a theme change.
function recolorCharts() {
  applyChartDefaults();
  for (const c of charts) {
    c.chart.destroy();
    c.chart = new Chart(c.canvas, chartConfig(c.ds, c.type));
  }
}

systemDark.addEventListener("change", () => {
  const toggle = document.querySelector("[data-theme-toggle]");
  if (toggle) updateThemeToggle(toggle);
  recolorCharts();
});

renderChrome();
applyChartDefaults();
document.querySelectorAll(".chart[data-dataset]").forEach(renderCard);
document.querySelectorAll("[data-catalog]").forEach(renderSources);
document.querySelectorAll("[data-library]").forEach(renderLibrary);
document.querySelectorAll("[data-changelog]").forEach(renderChangelog);
document.querySelectorAll("[data-ev-profiles]").forEach(renderEvProfiles);
